import com.vpscontrol.widget.UpdatePolicy;
public final class UpdatePolicyTest {
 static int n;static void check(boolean yes){n++;if(!yes)throw new AssertionError("update policy "+n);}
 public static void main(String[] args){String apk="https://github.com/"+UpdatePolicy.REPO+"/releases/download/android-v1.1.0/VPS-Control-Widget-1.1.0.apk";check(UpdatePolicy.artifact(apk));for(String bad:new String[]{apk.replace("https:","http:"),apk.replace("github.com/","github.com.evil.invalid/"),apk.replace("github.com/","evil@github.com/"),apk+"?token=secret",apk+"#fragment",apk.replace("Milunice259","attacker"),apk.replace("android-v1.1.0","android-v1.1.0-rc.1"),apk.replace(".apk",".zip"),apk.replace("releases/download/","releases/download/../download/")})check(!UpdatePolicy.artifact(bad));check(UpdatePolicy.redirect("https://release-assets.githubusercontent.com/asset?sig=test"));check(UpdatePolicy.redirect("https://objects.githubusercontent.com/asset"));for(String bad:new String[]{"http://release-assets.githubusercontent.com/x","https://evil.invalid/x","https://github.com/other.apk","https://release-assets.githubusercontent.com:123/x","https://user@release-assets.githubusercontent.com/x","https://release-assets.githubusercontent.com.evil.invalid/x"})check(!UpdatePolicy.redirect(bad));check(UpdatePolicy.version("1.1.0"));check(!UpdatePolicy.version("1.1.0-beta"));check(UpdatePolicy.digest("a".repeat(64)));check(!UpdatePolicy.digest("A".repeat(64)));check(UpdatePolicy.MAX_APK==500000);System.out.println("Update policy tests: PASS ("+n+" assertions)");}
}
